module pokemon_evolution(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] g1, g2,\n    input [5:0] types1, types2,\n    output reg [15:0] result,\n    output reg done\n);\n    // Precompute factorials for 0,1,2,3\n    function [15:0] factorial;\n        input [1:0] n;\n        begin\n            case(n)\n                2'd0: factorial = 16'd1;\n                2'd1: factorial = 16'd1;\n                2'd2: factorial = 16'd2;\n                2'd3: factorial = 16'd6;\n                default: factorial = 16'd1;\n            endcase\n        end\n    endfunction\n\n    // Type encoding: 01=1, 10=2, 11=3\n    reg [1:0] count_gym1_type1, count_gym1_type2, count_gym1_type3;\n    reg [1:0] count_gym2_type1, count_gym2_type2, count_gym2_type3;\n\n    // Count occurrences in gym1\n    integer i;\n    always @(*) begin\n        count_gym1_type1 = 2'd0;\n        count_gym1_type2 = 2'd0;\n        count_gym1_type3 = 2'd0;\n        for (i = 0; i < 3; i = i + 1) begin\n            if (i < g1) begin\n                case (types1[i*2 +: 2])\n                    2'b01: count_gym1_type1 = count_gym1_type1 + 2'd1;\n                    2'b10: count_gym1_type2 = count_gym1_type2 + 2'd1;\n                    2'b11: count_gym1_type3 = count_gym1_type3 + 2'd1;\n                    default: count_gym1_type1 = count_gym1_type1;\n                endcase\n            end\n        end\n    end\n\n    // Count occurrences in gym2\n    always @(*) begin\n        count_gym2_type1 = 2'd0;\n        count_gym2_type2 = 2'd0;\n        count_gym2_type3 = 2'd0;\n        for (i = 0; i < 3; i = i + 1) begin\n            if (i < g2) begin\n                case (types2[i*2 +: 2])\n                    2'b01: count_gym2_type1 = count_gym2_type1 + 2'd1;\n                    2'b10: count_gym2_type2 = count_gym2_type2 + 2'd1;\n                    2'b11: count_gym2_type3 = count_gym2_type3 + 2'd1;\n                    default: count_gym2_type1 = count_gym2_type1;\n                endcase\n            end\n        end\n    end\n\n    // Form keys (4-bit: gym1 count, gym2 count)\n    wire [3:0] key1 = {count_gym1_type1, count_gym2_type1};\n    wire [3:0] key2 = {count_gym1_type2, count_gym2_type2};\n    wire [3:0] key3 = {count_gym1_type3, count_gym2_type3};\n\n    // Group product calculation\n    reg [15:0] result_comb;\n    always @(*) begin\n        reg [1:0] group_count;\n        reg processed1, processed2, processed3;\n        result_comb = 16'd1;\n        processed1 = 1'b0;\n        processed2 = 1'b0;\n        processed3 = 1'b0;\n\n        if (!processed1) begin\n            group_count = 2'd1;\n            processed1 = 1'b1;\n            if (!processed2 && (key2 == key1)) begin\n                group_count = group_count + 2'd1;\n                processed2 = 1'b1;\n            end\n            if (!processed3 && (key3 == key1)) begin\n                group_count = group_count + 2'd1;\n                processed3 = 1'b1;\n            end\n            result_comb = result_comb * factorial(group_count);\n        end\n\n        if (!processed2) begin\n            group_count = 2'd1;\n            processed2 = 1'b1;\n            if (!processed3 && (key3 == key2)) begin\n                group_count = group_count + 2'd1;\n                processed3 = 1'b1;\n            end\n            result_comb = result_comb * factorial(group_count);\n        end\n\n        if (!processed3) begin\n            group_count = 2'd1;\n            processed3 = 1'b1;\n            result_comb = result_comb * factorial(group_count);\n        end\n    end\n\n    // Sequential output register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            result <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            if (start) begin\n                result <= result_comb;\n                done <= 1'b1;\n            end else begin\n                done <= 1'b0;\n            end\n        end\n    end\nendmodule